class Solution:
    def sumOfLargestPrimes(self, s: str) -> int:
        vals = {int(s[i:j]) for i in range(len(s)) for j in range(i + 1, len(s) + 1)}
        def isp(x):
            if x < 2: return False
            d = 2
            while d * d <= x:
                if x % d == 0: return False
                d += 1
            return True
        ps = sorted((x for x in vals if isp(x)), reverse=True)
        return sum(ps[:3])

