class Solution {
public:
    using u64 = unsigned long long;
    u64 mulmod(u64 a, u64 b, u64 m) { return (__uint128_t)a * b % m; }
    u64 powmod(u64 a, u64 e, u64 m) { u64 r = 1; a %= m; while (e) { if (e & 1) r = mulmod(r, a, m); a = mulmod(a, a, m); e >>= 1; } return r; }
    bool isp(u64 x) {
        if (x < 2) return false;
        for (u64 p : {2ull,3ull,5ull,7ull,11ull,13ull,17ull,19ull,23ull,29ull,31ull,37ull}) if (x % p == 0) return x == p;
        u64 d = x - 1; int r = 0;
        while (!(d & 1)) { d >>= 1; r++; }
        for (u64 a : {2ull,3ull,5ull,7ull,11ull,13ull,17ull,19ull,23ull,29ull,31ull,37ull}) {
            u64 v = powmod(a, d, x);
            if (v == 1 || v == x - 1) continue;
            bool comp = true;
            for (int i = 0; i < r - 1; i++) { v = mulmod(v, v, x); if (v == x - 1) { comp = false; break; } }
            if (comp) return false;
        }
        return true;
    }
    long long sumOfLargestPrimes(string s) {
