var sumOfLargestPrimes = function(s) {
    const vals = new Set();
    for (let i = 0; i < s.length; i++)
        for (let j = i + 1; j <= s.length; j++)
            vals.add(BigInt(s.slice(i, j)));
    const WIT = [2n,3n,5n,7n,11n,13n,17n,19n,23n,29n,31n,37n];
    const powmod = (a, e, m) => { let r = 1n; a %= m; while (e > 0n) { if (e & 1n) r = r * a % m; a = a * a % m; e >>= 1n; } return r; };
    const isp = (x) => {
        if (x < 2n) return false;
        for (const p of WIT) if (x % p === 0n) return x === p;
        let d = x - 1n, r = 0n;
        while (d % 2n === 0n) { d /= 2n; r++; }
        for (const a of WIT) {
            let v = powmod(a, d, x);
            if (v === 1n || v === x - 1n) continue;
            let comp = true;
            for (let i = 0n; i < r - 1n; i++) { v = v * v % x; if (v === x - 1n) { comp = false; break; } }
            if (comp) return false;
        }
        return true;
    };
    const ps = [...vals].filter(isp).sort((a, b) => (a < b ? 1 : -1));
    let ans = 0n;
    for (let i = 0; i < Math.min(3, ps.length); i++) ans += ps[i];
    return Number(ans);
};
